<script setup>
import {computed,ref} from 'vue'
const props=defineProps({result:Object,previous:Object}),emit=defineEmits(['pin','inspect-table','inspect-key']),expanded=ref(-1),notice=ref(''),compareKey=ref('id'),compare=ref(false)
const text=v=>v===null?'NULL':typeof v==='object'?JSON.stringify(v):String(v??'')
const pretty=v=>{if(typeof v==='object')return JSON.stringify(v,null,2);try{return JSON.stringify(JSON.parse(v),null,2)}catch{return text(v)}}
async function copy(v){try{await navigator.clipboard.writeText(text(v));notice.value='已复制'}catch{notice.value='浏览器不允许复制，请选中文本复制'}}
const difference=computed(()=>{if(!compare.value||!props.previous||!props.result)return null;const key=compareKey.value,a=props.previous.rows||[],b=props.result.rows||[];if(!props.result.columns.includes(key)||!props.previous.columns.includes(key))return {error:'请选择两次结果共有的唯一键列'};const index=rows=>{const m=new Map();for(const r of rows){const k=r[key];if(k===null||k===undefined||m.has(String(k)))throw Error('该列不是非空唯一键，无法可靠对比');m.set(String(k),r)}return m};try{const x=index(a),y=index(b);let added=0,changed=0,removed=0;for(const [k,v] of y){if(!x.has(k))added++;else if(JSON.stringify(v)!==JSON.stringify(x.get(k)))changed++}for(const k of x.keys())if(!y.has(k))removed++;return {added,changed,removed}}catch(e){return {error:e.message}}})
</script>
<template><div v-if="result" class="query-results"><div class="result-head"><b>查询结果</b><small>{{(result.rows||[]).length}} 行<span v-if="result.elapsed_ms!==undefined"> · {{result.elapsed_ms}} ms</span><span v-if="result.target"> · {{result.target.connection}} / {{result.target.database||'DB '+result.target.db}}</span></small><button type="button" @click="emit('pin')">保留本次结果作对照</button><button v-if="previous" type="button" @click="compare=!compare">{{compare?'收起对比':'对比保留结果'}}</button></div><p v-if="result.truncated||result.limit_reached" class="warning">{{result.truncated?'内容已截断，结果不完整。':'已达到行数上限，可能还有更多记录。'}}请缩小范围或使用主键分页。</p><div v-if="difference" class="comparison"><label>唯一键列 <select v-model="compareKey"><option v-for="col in result.columns" :key="col">{{col}}</option></select></label><span v-if="difference.error">{{difference.error}}</span><span v-else>新增 {{difference.added}} · 修改 {{difference.changed}} · 消失 {{difference.removed}}（仅对比已返回范围，不生成同步）</span></div><p v-if="notice" role="status">{{notice}}</p><div class="result-scroll"><table><thead><tr><th v-for="col in result.columns" :key="col">{{col}}</th><th>查看</th></tr></thead><tbody><template v-for="(row,i) in result.rows" :key="i"><tr><td v-for="col in result.columns" :key="col"><button class="cell" type="button" :title="'点击复制 '+col" @click="copy(row[col])">{{text(row[col])}}</button></td><td><button type="button" @click="expanded=expanded===i?-1:i">{{expanded===i?'收起':'详情'}}</button><button v-if="result.metadata==='tables'" type="button" @click="emit('inspect-table',row.table_name)">表结构</button></td></tr><tr v-if="expanded===i"><td :colspan="result.columns.length+1"><dl><template v-for="col in result.columns" :key="col"><dt>{{col}}</dt><dd><pre>{{pretty(row[col])}}</pre></dd></template></dl></td></tr></template></tbody></table><p v-if="!result.rows?.length">没有匹配的数据。</p></div></div></template>
<style scoped>
.query-results{border-top:1px solid var(--border);margin-top:12px;padding-top:12px;min-width:0}.result-head{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.result-head button{padding:4px 8px;font-size:12px}.result-head small{flex:1;color:var(--muted)}.warning{color:var(--warn);padding:6px 0}.result-scroll{margin-top:8px;max-height:420px;min-height:120px;overflow:auto;resize:vertical}table{min-width:500px}.cell{background:transparent;border:0;padding:0;text-align:left;max-width:360px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;display:block;font-family:var(--mono);font-size:12px}th{position:sticky;top:0;background:var(--panel2)}td{padding:8px 10px;vertical-align:top}td>button:not(.cell){padding:3px 8px;font-size:12px}dl{display:grid;grid-template-columns:120px minmax(0,1fr);gap:8px;padding:8px}dt{font-weight:600}pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:280px;overflow:auto;font:12px/1.6 var(--mono)}.comparison{display:flex;gap:12px;align-items:center;flex-wrap:wrap;padding:8px 0;font-size:12px}button:focus-visible{outline:2px solid var(--brand)}
</style>
